<!-- This file is generated by AI. -->
<!--
  生成失败的报错详情弹窗 (工作台任务项用)。

  GSOV 的原始报错是给日志看的 —— 颜色转义、星号横幅、几十行搜索路径, 铺在任务行里会把
  整栏撑爆, 所以列表里只留一行摘要 (`.error-chip`), 全文放到这里看, 并可一键复制去搜。

  ⚠️ 不带 `<style>` 块 —— 类名 (`.voice-error-detail` / `.voice-error-hint`) 来自全局 `styles.css`。
-->
<script lang="ts">
  import { onDestroy } from 'svelte';

  import { errorDetail, errorHint } from '../voice/errorText';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';

  let {
    /** 报错原文; null 表示不显示弹窗 */
    error,
    /** 标题下方的说明 (角色 / 类型 / 时间) */
    description,
    onClose,
  }: {
    error: string | null;
    description?: string;
    onClose: () => void;
  } = $props();

  const detail = $derived(error ? errorDetail(error) : '');
  const hint = $derived(error ? errorHint(error) : null);

  /** 复制按钮的三态; 失败也要说出来, 否则用户以为复制成功了 */
  let copyState = $state<'idle' | 'ok' | 'fail'>('idle');
  let resetTimer: ReturnType<typeof setTimeout> | undefined;

  async function copyReport(): Promise<void> {
    try {
      await navigator.clipboard.writeText(detail);
      copyState = 'ok';
    } catch {
      copyState = 'fail';
    }
    clearTimeout(resetTimer);
    resetTimer = setTimeout(() => (copyState = 'idle'), 1600);
  }

  onDestroy(() => clearTimeout(resetTimer));
</script>

{#if error}
  <AppDialog title="生成失败" {description} size="medium" height={380} {onClose}>
    <pre class="voice-error-detail">{detail}</pre>
    {#if hint}
      <!-- 可操作的那句提示放在原文之后: 用户先看到"是什么错", 再看"该怎么办" -->
      <p class="voice-error-hint">{hint}</p>
    {/if}

    {#snippet footer()}
      <Button icon="Copy" title="复制完整报错 (含搜索路径与堆栈)" onclick={() => void copyReport()}>
        {copyState === 'ok' ? '已复制' : copyState === 'fail' ? '复制失败' : '复制报错'}
      </Button>
      <Button appearance="primary" onclick={onClose}>关闭</Button>
    {/snippet}
  </AppDialog>
{/if}
